import {esc} from './ui.js';
import {properties,categories,articles,news} from './data.js';
import {propertyCard,newsCard} from './cards.js';

export function mountInteractions(){
 const dialog=document.querySelector('#home-dialog'),content=document.querySelector('#dialog-content');
 const open=html=>{content.innerHTML=html;dialog.showModal();};
 dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
 dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
 const consult=topic=>open(`<p class="eyebrow">Консультация</p><h2 id="dialog-title">${esc(topic)}</h2><p class="dialog-note">Демонстрационная форма. Данные остаются на этой странице и никуда не отправляются.</p><form class="consult-form"><label>Ваше имя<input name="name" autocomplete="given-name" required maxlength="80"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" required pattern="[+0-9\\s\\(\\)\\-]{7,25}" maxlength="25"></label><button class="pill" type="submit">Проверить заявку</button><p role="status" class="form-result"></p></form>`);
 document.addEventListener('click',event=>{
  const target=event.target.closest('button');if(!target)return;
  if(target.hasAttribute('data-consult'))consult(target.dataset.consult);
  if(target.hasAttribute('data-video'))open('<p class="eyebrow">Видео</p><h2 id="dialog-title">Видео агентства</h2><p class="dialog-note">В исходном макете размещена кнопка видео. Сам видеофайл не приложен; здесь можно будет подключить его позже.</p>');
  if(target.hasAttribute('data-calculator')){open(`<p class="eyebrow">Ипотечный калькулятор</p><h2 id="dialog-title">Ежемесячный платеж</h2><p class="dialog-note">Пример расчёта для макета. Ставка 8,4% взята из исходного дизайна.</p><form class="mortgage-form"><label>Стоимость квартиры, руб.<input name="price" type="number" min="100000" max="100000000" step="10000" value="2650000" required></label><label>Первоначальный взнос, руб.<input name="deposit" type="number" min="0" step="10000" value="530000" required></label><div class="form-columns"><label>Ставка, %<input name="rate" type="number" min="0" max="50" step="0.1" value="8.4" required></label><label>Срок, лет<input name="years" type="number" min="1" max="50" value="20" required></label></div><output class="payment-result" aria-live="polite"></output></form>`);updatePayment();}
  const item=target.dataset.article?articles.find(a=>a.id===target.dataset.article):target.dataset.news?news.find(a=>a.id===target.dataset.news):null;
  if(item)open(`<p class="eyebrow">${item.category}</p><h2 id="dialog-title">${item.title}</h2><p class="dialog-note">${item.author?`Автор: ${item.author}. `:''}В исходном макете есть только карточка. Полный материал пока не добавлен.</p>`);
  if(target.dataset.category!==undefined)setCategory(Number(target.dataset.category));
  if(target.dataset.carousel){const section=document.getElementById(target.dataset.carousel);const grid=section.querySelector('.property-grid,.news-grid,.article-grid');const nodes=[...grid.children];if(nodes.length<2)return;const current=Number(section.dataset.slide||0);const next=(target.dataset.index!==undefined?Number(target.dataset.index):current+Number(target.dataset.step)+nodes.length)%nodes.length;const shift=(next-current+nodes.length)%nodes.length;section.dataset.slide=String(next);grid.append(...nodes.slice(shift),...nodes.slice(0,shift));section.querySelectorAll('.carousel-dots button').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===next)));}
 });
 function setCategory(index){document.querySelectorAll('[data-category]').forEach((button,i)=>{button.setAttribute('aria-selected',String(i===index));button.tabIndex=i===index?0:-1;});const list=document.querySelector('#property-list');list.setAttribute('aria-labelledby',`category-${index}`);list.innerHTML=index<2?properties.map(propertyCard).join(''):'';const message=document.querySelector('.catalog-message');message.hidden=index<2;message.textContent=`В исходном макете нет карточек категории «${categories[index]}». Выберите «Новостройки» или «Квартиры».`;document.querySelector('#catalog .carousel-controls').hidden=index>=2;resetCarousel(document.querySelector('#catalog'));}
 document.querySelector('.catalog-tabs').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const current=Number(event.target.dataset.category);if(Number.isNaN(current))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?categories.length-1:(current+(event.key==='ArrowRight'?1:categories.length-1))%categories.length;setCategory(next);document.querySelector(`[data-category="${next}"]`).focus();});
 document.querySelector('#offers-only').addEventListener('change',event=>{document.querySelector('#news-list').innerHTML=news.filter(item=>!event.target.checked||item.id==='offer').map(newsCard).join('');document.querySelector('#news .carousel-controls').hidden=event.target.checked;resetCarousel(document.querySelector('#news'));});
 dialog.addEventListener('submit',event=>{event.preventDefault();if(event.target.matches('.consult-form')){event.target.querySelector('.form-result').textContent='Форма заполнена. Это демонстрация — заявка не отправлена.';} });
 dialog.addEventListener('input',event=>{if(event.target.closest('.mortgage-form'))updatePayment();});
 const resetCarousel=section=>{section.dataset.slide='0';const count=section.querySelector('.property-grid,.news-grid,.article-grid').children.length;section.querySelectorAll('.carousel-dots button').forEach((button,i)=>{button.disabled=i>=count;button.setAttribute('aria-pressed',String(i===0));if(i>=count)button.title='В исходном макете нет дополнительной карточки';else button.removeAttribute('title');});};
 document.querySelectorAll('#catalog,#news,#blog').forEach(resetCarousel);
 function updatePayment(){const form=dialog.querySelector('.mortgage-form');if(!form)return;const values=new FormData(form),price=Number(values.get('price')),deposit=Number(values.get('deposit')),rate=Number(values.get('rate'))/1200,months=Number(values.get('years'))*12;const output=form.querySelector('output');if(!form.checkValidity()||deposit>=price){output.textContent='Проверьте значения: взнос должен быть меньше стоимости.';return;}const loan=price-deposit,payment=rate===0?loan/months:loan*rate/(1-(1+rate)**(-months));output.innerHTML=`${Math.round(payment).toLocaleString('ru-RU')} ₽<small>в месяц · без страховки и комиссий</small>`;}
}
